function Avatar({ name, index = 0, large = false }) {
  const [bg, ink] = avatarColors[index % avatarColors.length];
  return <span className={`avatar ${large ? 'avatar-lg' : ''}`} style={{ '--avatar-bg': bg, '--avatar-ink': ink }}>{initials(name)}</span>;
}

function Button({ children, onClick, variant = 'secondary', type = 'button', className = '' }) {
  return <button type={type} onClick={onClick} className={`button ${variant} ${className}`}>{children}</button>;
}

function Card({ children, className = '' }) {
  return <section className={`card ${className}`}>{children}</section>;
}

