function KpiCard({ label, value, delta, alert = false }) {
  return <article className="kpi-card"><div className="kpi-label">{label}<span className="info-dot">i</span></div><strong>{value}</strong><div className={`kpi-delta ${alert ? 'alert' : ''}`}><b>{delta}</b> vs. previous period</div><svg className="spark" width="74" height="30" viewBox="0 0 74 30" fill="none"><path d="M1 25C8 21 12 23 17 18s8 3 14-3 7 2 13-4 9 1 14-5 7-2 15-7" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round"/><path d="M1 29h72" stroke="#e9eeea"/></svg></article>;
}

function UserTable({ title, copy, rows, top, share }) {
  return <div className="usage-panel"><div className="usage-head"><div><h3 className={top ? '' : 'low'}><span>{top ? '↑' : '↓'}</span>{title}</h3><p>{copy}</p></div><div className="usage-share"><b>{share}</b>of plan tokens</div></div><div className="table-scroll"><table className="compact-table"><thead><tr><th>#</th><th>Member</th><th className="right">Avg. tokens</th><th className="right">Model cost</th></tr></thead><tbody>{rows.map((row, i) => <tr key={row[1]}><td>{i + 1}</td><td><div className="member"><Avatar name={row[0]} index={i}/><div><b>{row[0]}</b><small>{row[1]}</small></div></div></td><td className="right">{row[2]}</td><td className="right strong">{row[3]}</td></tr>)}</tbody></table></div></div>;
}

